() => {
  var params = this.getComponent('purchase_invoice_no');
  const { options } = params;
  return options?.dynamicRuleField;
}

options.validator:
(async () => {
  // Read the cap off the row the event carries rather than off rule.field.
  // A bundle's items validate at a nested path (table_pi.0.children.1.…), and
  // splitting that path would take fieldParts[1] — the parent's index — so an
  // item would be checked against the bundle's available quantity instead of
  // its own.
  const availableInvQty = arguments[0].row.available_inv_qty;

  const positiveQty = Math.abs(value);
  if (positiveQty > availableInvQty) {
    callback("Invoice quantity cannot exceed available invoice quantity.");
    return;
  } else {
    callback();
  }
})();

