          };

          tablePI.push(piItemData);
          purchaseOrderNumber.push(po.purchase_order_no);
          poID.push(po.id);
        });
      }
    }

    // Set the data after processing all POs
    if (tablePI.length > 0) {
      purchaseOrderNumber = [...new Set(purchaseOrderNumber)];
