            this.disabled(
              [`table_pi.${lineItemIndex}.tax_rate_percent`],
              false
            );
          }
        });
      }, 1000);

      this.triggerEvent("PIcalculation", { PIlineItem: tablePI });
    }
  } catch (error) {
    this.$message.error(error.toString());
  }
})();

